pub fn row_eq_weight(p: &[E; 10]) -> Message<E> {
    core::array::from_fn(|r| {
        (0..10).fold(E::ONE, |v, b| {
            v.mul(if (r >> b) & 1 == 0 {
                E::ONE.sub(p[b])
            } else {
                p[b]
            })
        })
    })
}
