        const N: usize = 49;
        let mut state = 0x8f31_50a2_d192_ed03u64;
        let mut next = || {
            state ^= state >> 12;
            state ^= state << 25;
            state ^= state >> 27;
            M31((state.wrapping_mul(0x2545_f491_4f6c_dd1d) as u32) % P)
        };
